//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::repr::string_quote`; the
//! native twin is `benches/native/Bench/ReprStringQuote.lean`.
//! Lean code natively (small strings and appends); the Rust twin formats on the stack and makes
//! one new string object, its characters counted; 16 strings of 30 to 60 bytes with escapes

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::repr;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<String>, n: u64) -> u64 {
    let ss = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let s = get_string(ss, x >> 60);
            let mut b = StackBuf::new();
            let _ = repr::string_quote(s, &mut b);
            make_string(b.as_bytes()).byte_size()
        });
    }
    acc
}

fn main() {
    run(|| quote_strings(), kernel)
}
